inputs = ['iwiu', 'hfcgd', 'hhzkvj', 'uuav', 'dyvbi']
outputs = ['iwidbd', 'hfcbd', 'hhzkvj', 'dbddbdvfdbdv', 'dyvbi']

print("Input -> Output:")
for i in range(len(inputs)):
    print(f"{inputs[i]} -> {outputs[i]}")

print("\nAnalyzing differences:")
for i in range(len(inputs)):
    inp = inputs[i]
    out = outputs[i]
    if inp != out:
        print(f"  {inp} vs {out}")
        # Find where they differ
        for j in range(min(len(inp), len(out))):
            if inp[j] != out[j]:
                print(f"    Diff at position {j}: '{inp[j]}' -> '{out[j]}'")
                break
        else:
            if len(inp) != len(out):
                print(f"    Length change: {len(inp)} -> {len(out)}")

